"""P2-pのR5宣言。満たされた exchange の行が出力先の構造（FHIR R5 Observation）で、丸めず・閉じず・補わずに表せるかを診断する合成の拡張の17義務（共通4＋R5の3＋GR-1〜10）。"""
import hashlib


def grounding_manifest(root):
    tests = 'tests/p2/test_grounding.py::GroundingTests.'
    mutants = 'test_selected_mutants_are_detected_by_reference'
    first = lambda name: name if isinstance(name, list) else [name]
    rows = [
        ('K-ID', '自己・P2-oの版と実体を固定し、旧profileや他拡張の結果を代用しない', 'test_static_validation_pins_limits_and_native_refusals',
         'N02-profile_spec_sha256', ['status'], 'unsupported_profile', False, 'refusal'),
        ('K-STOP', 'P2-oの停止（能力・選択・要素）を先に通し、構造の判定は満たされた行だけに行う', 'test_other_rows_pass_through_and_representable_rows_keep_the_library_columns',
         'R03', ['results', 0, 'reason_codes'], ['unknown_capability'], False, 'boundary'),
        ('K-INV', '推測で補った情報を作らず、入力を変更せず、臨床の主張を追加しない', 'test_nothing_is_rounded_closed_or_added',
         'G01', ['inferred_information'], [], False, 'non_conversion'),
        ('K-RES', '共通予算に従い、未完了の行に値を返さず、資源停止で認定しない', 'test_budget_sweep_keeps_finished_rows_and_has_no_partial_values',
         'B01-36', ['certificate', 'status'], 'not_certified', False, 'boundary'),
        ('R5-1', '構造の判定が診断であり、足した仮定（期間の端の規約）を示す', 'test_hand_expectations_api_cli_manifest_and_obligations',
         'P02', ['results', 0, 'flows', 'added'], ['assumption:end_convention:last_second', 'assumption:second_granularity'], False, 'boundary'),
        ('R5-2', '保存・医学的な意味の認定を出さない', 'test_nothing_is_rounded_closed_or_added',
         'G01', ['certificate', 'status'], 'not_certified', False, 'non_conversion'),
        ('R5-3', '構造への適合・臨床の傾向・基底への変換を主張しない', 'test_nothing_is_rounded_closed_or_added',
         'G01', ['converted_to_base'], False, False, 'non_conversion'),
        ('GR-1', '自己・P2-oのprofileと仕様hash、構造の事実の出典のハッシュを固定し、呼び出し側が事実を変えられない',
         ['test_static_validation_pins_limits_and_native_refusals', 'test_structure_facts_are_bound_to_their_sources'],
         'N02-library_profile_spec_sha256', ['reason_codes'], ['library_profile_mismatch'], False, 'refusal'),
        ('GR-2', '確認を作らず、人の確認と出自の種類を運べないものとして常に失うものに残す', 'test_period_conventions_and_context_carriage_over_the_enumeration',
         'G01', ['results', 0, 'flows', 'lost'],
         ['context:property', 'human_confirmed', 'origin_kind', 'quantity_kind', 'record:identity', 'review:identity', 'revision_history', 'validity'], True, 'boundary'),
        ('GR-3', 'P2-oの選択をそのまま使い、再選択しない', 'test_other_rows_pass_through_and_representable_rows_keep_the_library_columns',
         'P06', ['results', 0, 'selection', 'record_ref'], 'B', True, 'boundary'),
        ('GR-4', '停止の順序（P2-oの停止→静的検査→値→期間→文脈）と状態の優先を守る', 'test_other_rows_pass_through_and_representable_rows_keep_the_library_columns',
         'R01', ['results', 1, 'grounding', 'state'], 'not_evaluated', True, 'boundary'),
        ('GR-5', '全体の料金・子の予約の使い切り・原子性・最後の確定を照合する',
         ['test_full_cost_funded_once_and_the_child_uses_its_reservation', 'test_child_failure_and_mismatch_are_atomic_and_refused'],
         'G01', ['steps_used'], 37, True, 'boundary'),
        ('GR-6', '丸めない・閉じない・補わない。仮定は宣言した規約だけで、流れに残る', ['test_nothing_is_rounded_closed_or_added', mutants],
         'G22', ['results', 0, 'reason_codes'], ['open_boundary_not_representable'], True, 'non_conversion'),
        ('GR-7', '値（点・区間、有限小数、桁数）と期間の端の規約の判定規則', ['test_value_rules_over_the_finite_grid_against_the_oracle',
                                                      'test_period_conventions_and_context_carriage_over_the_enumeration', mutants],
         'G03', ['results', 0, 'reason_codes'], ['not_decimal_representable'], True, 'boundary'),
        ('GR-8', '失う区別（文脈の三状態）と足す仮定を、根拠つきで流れに報告する', ['test_period_conventions_and_context_carriage_over_the_enumeration', mutants],
         'C01', ['results', 0, 'grounding', 'projection', 'absent'], ['method'], True, 'boundary'),
        ('GR-9', '構造の事実が、取得したページの出典（台帳のid・ハッシュ・目印の語）に結ばれ、未知の構造を拒否する', 'test_structure_facts_are_bound_to_their_sources',
         'N08-structure', ['reason_codes'], ['unsupported_structure'], False, 'refusal'),
        ('GR-10', '判定していない行（対象のない出力先、満たされない行）を、写像できると言わない', ['test_other_rows_pass_through_and_representable_rows_keep_the_library_columns', mutants],
         'D01', ['results', 0, 'grounding', 'state'], 'not_declared', True, 'boundary')]
    obligations = [{'id': ident, 'statement': text, 'evidence': 'finite_check' if finite else 'checked_native_template',
                    'checks': [tests+name for name in first(test)],
                    'guards': [{'example': 'examples/p2-grounding/'+example.lower()+'.json', 'path': path, 'equals': value, 'kind': kind}]}
                   for ident, text, test, example, path, value, finite, kind in rows]
    return {'schema_version': 'p2-extension-manifest-draft-2', 'id': 'p2-structure-grounding', 'version': 'draft-1',
            'title': '満たされた exchange の行が、出力先の構造（FHIR R5 Observation）で、丸めず・閉じず・補わずに表せるかを診断する',
            'status': {'review_state': 'author_draft', 'independent_review': False}, 'class': 'R5',
            'spec': {'path': 'src/med_dsl/structure_grounding_spec.json', 'sha256': hashlib.sha256((root/'src/med_dsl/structure_grounding_spec.json').read_bytes()).hexdigest()},
            'contract_doc': 'docs/research/67-p2-p-design.md', 'implementation': {'modules': ['src/med_dsl/structure_grounding.py']},
            'pins': [{'path': 'src/med_dsl/host.py', 'role': 'dispatcher'}, {'path': 'docs/research/68-p2-p-cases.md', 'role': 'hand_specified_expectations'},
                     {'path': 'src/med_dsl/clinical_library_spec.json', 'role': 'clinical_library_native_spec'},
                     {'path': 'src/med_dsl/temporal_measurement_spec.json', 'role': 'temporal_measurement_native_spec'},
                     {'path': 'src/med_dsl/quantity_spec.json', 'role': 'quantity_native_spec'}],
            'embedded_in': ['src/med_dsl/structure_grounding_spec.json', 'src/med_dsl/clinical_library.py', 'examples/p2-grounding/*.json', 'examples/p2-library/*.json'],
            'depends_on': [{'id': 'p0-positive', 'version': 'draft-2'}, {'id': 'p2-clinical-library', 'version': 'draft-1'}],
            'owns': {'operations': ['run_structure_grounding'], 'schema_versions': ['p2-grounding-request-draft-1', 'p2-grounding-result-draft-1'],
                     'profiles': ['p2-structure-grounding-draft-1'], 'answer_kinds': ['structure_grounding_projection'], 'predicates': [],
                     'capabilities': ['p2-structure-grounding-draft-1']},
            'scope': {'base_requests': '旧要求とP2-o・P2-i・P2-fを変えず、P2-oを固定版で一度だけ実行し、満たされたexchangeの行にだけ構造への写像の可否を判定する',
                      'fragment': '構造 fhir-r5-observation の一つだけ。値（quantity・range）、期間の端の規約、文脈（method・specimen）の運び方、運べないもの。status・code・Provenance・Quantityのcomparator・コード化した単位は範囲外。FHIRへの適合は主張しない'},
            'obligations': obligations,
            'stops': {'unknown_capability': 'P2-oの停止（能力・選択・要素）の行は、そのまま通し not_evaluated と明示する',
                      'unsupported': 'unsupported_profile。未知の構造・値の型・期間の規約・文脈の欄・出力の種類を補完しない',
                      'resource': 'resource_limit。未完了の七欄は全てnull、完成料金前は認定なし、子の部分結果は使わない',
                      'invalid_input': '子の要求（P2-oの検査）と対象の宣言を予算前に検査'},
            'composition': {'shares_names_with': [], 'reads_extensions': ['p2-clinical-library'], 'order_dependent': False},
            'evaluation': {'examples': ['examples/p2-grounding/*.json'], 'tests': ['tests/p2/test_grounding.py'], 'budget_sweep': True, 'oracle': 'tests/p2/grounding_oracle.py'}}
